#include "rank.h"
#include "text.h"
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <errno.h>
#include <zlib.h>

namespace {
void* checked(void* p){if(!p){fprintf(stderr,"rank: allocation failed\n");exit(2);}return p;}
char* copy(const char* p){size_t n=strlen(p)+1;char* result=(char*)checked(malloc(n));memcpy(result,p,n);return result;}
struct Buffer{char* data;size_t size,capacity;Buffer():data(NULL),size(0),capacity(0){}~Buffer(){free(data);}void reserve(size_t n){if(n<=capacity)return;size_t c=capacity?capacity:256;while(c<n)c*=2;data=(char*)checked(realloc(data,c));capacity=c;}void append(const char* p,size_t n){reserve(size+n+1);memcpy(data+size,p,n);size+=n;data[size]=0;}void clear(){size=0;if(data)data[0]=0;}};
uint64_t hash(const char* p){uint64_t result=1469598103934665603ULL;for(;*p;p++){result^=(unsigned char)*p;result*=1099511628211ULL;}return result;}
struct Slot{char* key;int value;};
struct Map{Slot* slots;size_t capacity,used;Map():slots(NULL),capacity(0),used(0){resize(128);}~Map(){for(size_t i=0;i<capacity;i++)free(slots[i].key);free(slots);}void resize(size_t n){Slot* old=slots;size_t oldn=capacity;slots=(Slot*)checked(calloc(n,sizeof(Slot)));capacity=n;for(size_t i=0;i<oldn;i++)if(old[i].key){size_t at=hash(old[i].key)&(n-1);while(slots[at].key)at=(at+1)&(n-1);slots[at]=old[i];}free(old);}bool get(const char* key,int& value)const{size_t at=hash(key)&(capacity-1);while(slots[at].key){if(!strcmp(slots[at].key,key)){value=slots[at].value;return true;}at=(at+1)&(capacity-1);}return false;}void put(const char* key,int value){if((used+1)*10>=capacity*7)resize(capacity*2);size_t at=hash(key)&(capacity-1);while(slots[at].key&&strcmp(slots[at].key,key))at=(at+1)&(capacity-1);if(!slots[at].key){slots[at].key=copy(key);used++;}slots[at].value=value;}};
struct Query{char* id;uint32_t* terms;uint32_t* frequency;size_t size,capacity;void add(uint32_t term){for(size_t i=0;i<size;i++)if(terms[i]==term){frequency[i]++;return;}if(size==capacity){capacity=capacity?capacity*2:16;terms=(uint32_t*)checked(realloc(terms,capacity*sizeof(uint32_t)));frequency=(uint32_t*)checked(realloc(frequency,capacity*sizeof(uint32_t)));}terms[size]=term;frequency[size++]=1;}void release(){free(id);free(terms);free(frequency);}};
struct Queries{Query* items;size_t size,capacity;Queries():items(NULL),size(0),capacity(0){}~Queries(){for(size_t i=0;i<size;i++)items[i].release();free(items);}Query* add(const char* id){for(size_t i=0;i<size;i++)if(!strcmp(items[i].id,id))return NULL;if(size==capacity){capacity=capacity?capacity*2:32;items=(Query*)checked(realloc(items,capacity*sizeof(Query)));}Query* q=&items[size++];q->id=copy(id);q->terms=NULL;q->frequency=NULL;q->size=q->capacity=0;return q;}};
struct Normalize{const char* mode;Map* union_terms;Map cache;Buffer buffer;Normalize(const char* m,Map* terms):mode(m),union_terms(terms){}const char* token(const char* input,size_t n){buffer.reserve(n+64);memcpy(buffer.data,input,n);buffer.data[n]=0;if(!strcmp(mode,"stem"))ir_stem(buffer.data);else if(!strcmp(mode,"lemma")){Buffer result;result.reserve(n+64);if(!ir_lemma_copy(input,result.data,result.capacity)){fprintf(stderr,"rank: lemma output exceeds capacity\n");exit(2);}memcpy(buffer.data,result.data,strlen(result.data)+1);}return buffer.data;}int find(const char* input,size_t n){if(!strcmp(mode,"raw")){int value;return union_terms->get(input,value)?value:-1;}int value;if(cache.get(input,value))return value;const char* normalized=token(input,n);value=-1;union_terms->get(normalized,value);cache.put(input,value);return value;}};
struct QueryContext{Query* query;Map* terms;Normalize* normalization;};
void query_token(const char* token,size_t n,void* user){QueryContext* c=(QueryContext*)user;const char* term=c->normalization->token(token,n);int id;if(!c->terms->get(term,id)){id=(int)c->terms->used;c->terms->put(term,id);}c->query->add((uint32_t)id);}
bool read_queries(const char* path,const char* mode,Queries& queries,Map& terms){FILE* f=fopen(path,"r");if(!f){perror(path);return false;}char* line=NULL;size_t cap=0;ssize_t n;Normalize normal(mode,&terms);bool first=true;while((n=getline(&line,&cap,f))>=0){while(n&&(line[n-1]=='\n'||line[n-1]=='\r'))line[--n]=0;if(!n)continue;char* tab=strchr(line,'\t');if(!tab||tab==line){fprintf(stderr,"rank: malformed query TSV\n");free(line);fclose(f);return false;}*tab=0;if(first&&(!strcmp(line,"query_id")||!strcmp(line,"qid"))&&(!strcmp(tab+1,"query")||!strcmp(tab+1,"text"))){first=false;continue;}first=false;Query* q=queries.add(line);if(!q){fprintf(stderr,"rank: duplicate query ID %s\n",line);free(line);fclose(f);return false;}QueryContext context={q,&terms,&normal};ir_tokenize(tab+1,strlen(tab+1),query_token,&context);}bool ok=!ferror(f);free(line);fclose(f);if(!queries.size){fprintf(stderr,"rank: no queries\n");return false;}return ok;}
struct Document{uint32_t id;uint64_t length;uint32_t* counts;};
struct Documents{Document* items;size_t size,capacity;uint64_t total_length;Documents():items(NULL),size(0),capacity(0),total_length(0){}~Documents(){for(size_t i=0;i<size;i++)free(items[i].counts);free(items);}Document* add(uint32_t id,size_t terms){if(size==capacity){capacity=capacity?capacity*2:128;items=(Document*)checked(realloc(items,capacity*sizeof(Document)));}Document* d=&items[size++];d->id=id;d->length=0;d->counts=(uint32_t*)checked(calloc(terms?terms:1,sizeof(uint32_t)));return d;}};
struct DocContext{Document* document;Normalize* normalization;};
void document_token(const char* token,size_t n,void* user){DocContext* c=(DocContext*)user;c->document->length++;int term=c->normalization->find(token,n);if(term>=0){if(c->document->counts[term]==UINT32_MAX){fprintf(stderr,"rank: document term count overflow\n");exit(2);}c->document->counts[term]++;}}
bool read_gzip(const char* path,Buffer& text){text.clear();gzFile file=gzopen(path,"rb");if(!file){fprintf(stderr,"rank: cannot open %s\n",path);return false;}char bytes[65536];int n;while((n=gzread(file,bytes,sizeof(bytes)))>0)text.append(bytes,(size_t)n);if(n<0){int code;fprintf(stderr,"rank: read failed %s: %s\n",path,gzerror(file,&code));gzclose(file);return false;}if(gzclose(file)!=Z_OK){fprintf(stderr,"rank: gzip close failed %s\n",path);return false;}return true;}
bool read_documents(const char* path,const char* mode,Map& terms,Documents& docs,uint32_t* df){FILE* f=fopen(path,"r");if(!f){perror(path);return false;}char* line=NULL;size_t cap=0;ssize_t n=getline(&line,&cap,f);if(n<0||strncmp(line,"id\tpath\t",8)){fprintf(stderr,"rank: document TSV header must start id,path\n");free(line);fclose(f);return false;}Normalize normal(mode,&terms);Buffer text;while((n=getline(&line,&cap,f))>=0){char* first=strchr(line,'\t');char* second=first?strchr(first+1,'\t'):NULL;if(!first||!second){fprintf(stderr,"rank: malformed document TSV\n");free(line);fclose(f);return false;}*first=0;*second=0;char* end=NULL;errno=0;unsigned long id=strtoul(line,&end,10);if(errno||!end||*end||id>UINT32_MAX||id!=docs.size){fprintf(stderr,"rank: document IDs must be contiguous from zero\n");free(line);fclose(f);return false;}if(!read_gzip(first+1,text)){free(line);fclose(f);return false;}Document* d=docs.add((uint32_t)id,terms.used);DocContext context={d,&normal};ir_tokenize(text.data?text.data:"",text.size,document_token,&context);docs.total_length+=d->length;for(size_t i=0;i<terms.used;i++)if(d->counts[i])df[i]++;if(docs.size%5000==0)fprintf(stderr,"rank documents: %zu\n",docs.size);}bool ok=!ferror(f);free(line);fclose(f);fprintf(stderr,"rank corpus_documents=%zu total_tokens=%llu query_terms=%zu\n",docs.size,(unsigned long long)docs.total_length,terms.used);return ok;}
struct Hit{uint32_t id;double score;};
struct TopFive{Hit hits[5];size_t size;TopFive():size(0){}void add(uint32_t id,double score){size_t at=0;while(at<size&&(hits[at].score>score||(hits[at].score==score&&hits[at].id<id)))at++;if(at>=5)return;size_t end=size<5?size:4;for(size_t i=end;i>at;i--)hits[i]=hits[i-1];hits[at]=Hit{id,score};if(size<5)size++;}};
void escaped(const char* value){fputc('"',stdout);for(const unsigned char* p=(const unsigned char*)value;*p;p++){if(*p=='"'||*p=='\\'){fputc('\\',stdout);fputc(*p,stdout);}else if(*p<32)fprintf(stdout,"\\u%04x",*p);else fputc(*p,stdout);}fputc('"',stdout);}
void hits_json(const TopFive& hits,bool scores){fputc('[',stdout);for(size_t i=0;i<hits.size;i++){if(i)fputc(',',stdout);if(scores)fprintf(stdout,"%.17g",hits.hits[i].score);else fprintf(stdout,"%u",hits.hits[i].id);}fputc(']',stdout);}
void evaluate(const Queries& queries,const Documents& docs,const uint32_t* df){double avg=docs.size?(double)docs.total_length/docs.size:0;for(size_t qi=0;qi<queries.size;qi++){const Query& q=queries.items[qi];TopFive boolean,tfidf,bm25;for(size_t di=0;di<docs.size;di++){const Document& d=docs.items[di];bool all=q.size>0,any=false;double tfidf_score=0,bm25_score=0;for(size_t i=0;i<q.size;i++){uint32_t term=q.terms[i],tf=d.counts[term];if(!tf){all=false;continue;}any=true;double idf=1+log(((double)docs.size+1)/(df[term]+1.0));if(d.length)tfidf_score+=q.frequency[i]*(double)tf/d.length*idf*idf;double bm_idf=log(1+((double)docs.size-df[term]+0.5)/(df[term]+0.5));double divisor=tf+1.2*(1-0.75+(avg?0.75*d.length/avg:0));if(divisor)bm25_score+=q.frequency[i]*bm_idf*tf*(1.2+1)/divisor;}if(all)boolean.add(d.id,0);if(any){tfidf.add(d.id,tfidf_score);bm25.add(d.id,bm25_score);}}
 fputs("{\"query_id\":",stdout);escaped(q.id);fputs(",\"boolean\":",stdout);hits_json(boolean,false);fputs(",\"tfidf\":",stdout);hits_json(tfidf,false);fputs(",\"bm25\":",stdout);hits_json(bm25,false);fputs(",\"tfidf_scores\":",stdout);hits_json(tfidf,true);fputs(",\"bm25_scores\":",stdout);hits_json(bm25,true);fprintf(stdout,",\"corpus_documents\":%zu}\n",docs.size);
 }}
}

int ir_rank_main(int argc,char** argv){if(argc<3||argc>4){fprintf(stderr,"usage: rank DOCUMENTS_TSV QUERIES_TSV [stem|raw|lemma]\n");return 2;}const char* mode=argc==4?argv[3]:"stem";if(strcmp(mode,"stem")&&strcmp(mode,"raw")&&strcmp(mode,"lemma")){fprintf(stderr,"rank: unknown normalization %s\n",mode);return 2;}Queries queries;Map terms;if(!read_queries(argv[2],mode,queries,terms))return 1;Documents docs;uint32_t* df=(uint32_t*)checked(calloc(terms.used?terms.used:1,sizeof(uint32_t)));if(!read_documents(argv[1],mode,terms,docs,df)){free(df);return 1;}evaluate(queries,docs,df);free(df);return ferror(stdout)?1:0;}
